function ic(name,size=19,cls=''){return `<svg class="icon ${cls}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;}
const escapeHtml = val => String(val ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => '$' + Number(n || 0).toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:2});
const fmt = n => Number(n||0).toLocaleString('en-US');
const timeAgo = v => { const min = Math.max(0,Math.round((Date.now()-new Date(v).getTime())/60000));return min < 1?'Just now':min<60?`${min}m ago`:min<1440?`${Math.floor(min/60)}h ago`:`${Math.floor(min/1440)}d ago`; };
const sessionId = (()=>{const key='decisiongap.session';let sid=sessionStorage.getItem(key);if(!sid){sid=`buyer-${crypto.randomUUID()}`;sessionStorage.setItem(key,sid);}return sid;})();
const state = {data:null,loginRequired:false,loginError:'',page:'overview',view:new URLSearchParams(location.search).get('view')==='store'?'store':'dashboard',cart:[],cartOpen:false,chatOpen:false,chatLoading:false,chatMessages:[{speaker:'agent',text:"Hi! I'm Nova, your AI shopping assistant. Tell me what you're shopping for, and I'll help you find the right fit — no pressure."}],selectedProduct:'nova-pro',filter:'All',busy:false,order:null};
async function api(path, opts={}){
 const res = await fetch(path,{headers:{'content-type':'application/json'},...opts,body:opts.body?JSON.stringify(opts.body):undefined});
 const data = await res.json();
 if(!res.ok){const e=new Error(data.error||'Something went wrong.');e.status=res.status;throw e;}return data;
}
async function load(){
  try {
    state.data=await api(state.view==='store'?'/api/storefront':'/api/bootstrap');
    state.loginRequired=false;
    if (state.data?.products?.length && !state.data.products.some(p=>p.id===state.selectedProduct)) state.selectedProduct=state.data.products[0].id;
  } catch(e) {
    if (state.view==='dashboard' && e.status===401) {
      state.data=null; state.loginRequired=true;
    } else throw e;
  }
  render();
}
function toast(text,type='success'){const host=$('#toast-root');const el=document.createElement('div');el.className=`toast ${type}`;el.innerHTML=`${ic(type==='error'?'info':'check',17)} <span>${escapeHtml(text)}</span>`;host.appendChild(el);setTimeout(()=>el.remove(),4000);}
function setPage(name){state.page=name;render();window.scrollTo({top:0,behavior:'smooth'});}
function badge(text,kind='neutral'){return `<span class="badge badge-${kind}">${escapeHtml(text)}</span>`;}
function productArt(p,small=false){return `<div class="product-art ${escapeHtml(p.color||'lavender')} ${small?'art-small':''}"><div class="product-halo"></div>${p.imageUrl&&p.imageUrl.startsWith('https://')?`<img class="product-photo" src="${escapeHtml(p.imageUrl)}" alt="${escapeHtml(p.name)}" loading="lazy">`:ic(p.icon,small?48:85,'product-icon')}<span class="art-dot dot-a"></span><span class="art-dot dot-b"></span></div>`; }
function brand(){return `<div class="brand"><span class="brand-symbol">${ic('spark',23)}</span><div><strong>decisiongap<span class="brand-os">OS</span></strong><small>INTELLIGENCE ENGINE</small></div></div>`;}
function pageHead(eyebrow,title,subtitle,right=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${right}</div>`;}
function navLink(key,icon,label,sub=''){return `<button class="side-link ${state.page===key?'active':''}" data-action="navigate" data-target="${key}">${ic(icon,19)}<span>${label}</span>${sub?`<span class="side-count">${sub}</span>`:''}</button>`;}
function sidebar(){return `<aside class="sidebar">${brand()}<div class="workspace-switch"><div class="workspace-avatar">D</div><div><strong>${escapeHtml(state.data.merchant.name)}</strong><small>${state.data.demo?'Demo workspace':'Connected store'}</small></div>${ic('chevron',17)}</div><div class="side-label">WORKSPACE</div><nav class="sidebar-nav">${navLink('overview','grid','Overview')}${navLink('intelligence','brain','Customer intelligence')}${navLink('agent','agent','AI sales agent','LIVE')}${navLink('experiments','chart','Experiments')}${navLink('growth','bolt','Growth Studio','NEW')}${navLink('commerce','bag','Commerce setup')}${navLink('settings','sliders','Settings')}</nav><div class="side-bottom"><div class="side-promo"><div class="promo-stars">✳ &nbsp; BUILT FOR BETTER DECISIONS</div><h4>From insight<br>to impact.</h4><p>See the AI salesperson in action.</p><button data-action="open-store" class="promo-btn">Open storefront ${ic('arrowUp',15)}</button></div><div class="sidebar-footer">${ic('shield',15)} ${state.data.demo?'Demo · simulated purchases':'Shopify · secure hosted checkout'}</div></div></aside>`;}
function topbar(){return `<header class="topbar"><div class="crumbs">Workspace ${ic('chevron',15)} <span>${escapeHtml({overview:'Overview',intelligence:'Customer intelligence',agent:'AI sales agent',experiments:'Experiments',growth:'Growth Studio',commerce:'Commerce setup',settings:'Settings'}[state.page])}</span></div><div class="top-right"><span class="top-status"><i></i> ${state.data.merchant.policy.aiEnabled?'AI agent active':'AI agent paused'}</span><button class="top-store" data-action="open-store">${ic('bag',17)} Open storefront ${ic('arrowUp',14)}</button><button class="top-store" data-action="logout" title="Log out of dashboard">${ic('lock',16)} Log out</button><div class="avatar">NA</div></div></header>`;}
function overview(){
 const d=state.data,a=d.analytics,top=d.insights;
 const vals=a.week.map(x=>x.visits),max=Math.max(...vals,1);
 const points=a.week.map((x,i)=>`${30+i*(680/6)},${170-(x.visits/max)*125}`).join(' ');
 const area=`30,180 ${points} 710,180`;
 return `${pageHead('YOUR COMMAND CENTER','Good decisions create growth.','A unified view of customer friction, AI actions, and business outcomes.',`<div style="display:flex;gap:10px;flex-wrap:wrap"><button class="outline-btn" data-action="download-report">${ic('chart',15)} Export CSV</button><button class="outline-btn" data-action="open-store">Preview storefront ${ic('arrowUp',15)}</button></div>`)}
 <div class="hero-panel"><div class="hero-orb one"></div><div class="hero-orb two"></div><div class="hero-copy"><span class="hero-kicker"><span class="small-pulse"></span> INTRODUCING YOUR AUTONOMOUS SALES INTELLIGENCE</span><h2>Stop guessing why<br>customers <em>hesitate.</em></h2><p>Find the real barriers to buying. Let your AI agent help customers make confident decisions, then learn what works.</p><div class="hero-buttons"><button class="primary-btn" data-action="navigate" data-target="intelligence">Explore insights ${ic('arrow',18)}</button><button class="hero-link" data-action="navigate" data-target="agent">Meet your AI agent ${ic('chevron',17)}</button></div></div><div class="hero-visual"><div class="floating-card fc-top"><div class="fc-icon violet-bg">${ic('brain',21)}</div><div><small>CUSTOMER INSIGHT</small><strong>Warranty concerns detected</strong></div>${ic('check',18,'fc-check')}</div><div class="hero-glow"><div class="hero-glyph">${ic('spark',86)}</div></div><div class="floating-card fc-bottom"><div class="fc-icon green-bg">${ic('bolt',21)}</div><div><small>AGENT ACTION</small><strong>Trust-first guidance ready</strong></div><span class="live-mini">ACTIVE</span></div></div></div>
 <div class="metric-row">${metric('Store visitors',fmt(a.visitors),'chartBar','Traffic across the demo period','purple')}${metric('Completed orders',fmt(a.orders),'bag',d.demo?'Simulated purchases':'Webhook-confirmed paid orders','blue')}${metric('Conversion rate',a.conversion+'%','arrowUp','Orders ÷ visitors','mint')}${metric('Attributed revenue',money(a.revenue),'bolt',d.demo?'Synthetic order value':'Webhook-confirmed gross orders','orange')}</div>
 <div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-heading"><div><h3>Shopping activity</h3><p>Visitors over the past 7 days</p></div><span class="subtle-pill">Last 7 days ${ic('chevron',13)}</span></div><div class="chart-body"><div class="chart-y"><span>${Math.ceil(max/50)*50}</span><span>${Math.ceil(max/100)*25}</span><span>0</span></div><div class="chart-container"><div class="chart-gridline" style="top:16%"></div><div class="chart-gridline" style="top:49%"></div><div class="chart-gridline" style="top:82%"></div><svg class="line-chart" viewBox="0 0 740 190" preserveAspectRatio="none" role="img" aria-label="Weekly visits line chart"><defs><linearGradient id="graph-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#755df3" stop-opacity=".23"/><stop offset="100%" stop-color="#755df3" stop-opacity="0"/></linearGradient></defs><polygon points="${area}" fill="url(#graph-fill)"/><polyline points="${points}" stroke="#7264e9" stroke-width="4" stroke-linejoin="round" stroke-linecap="round" fill="none"/>${a.week.map((p,i)=>`<circle cx="${30+i*680/6}" cy="${170-p.visits/max*125}" r="5" fill="#fff" stroke="#7264e9" stroke-width="3"/>`).join('')}</svg><div class="chart-labels">${a.week.map(p=>`<span>${new Date(p.date+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'})}</span>`).join('')}</div></div></div><div class="chart-legend"><span><i class="legend-dot"></i> Visitors</span><span class="soft-note">Sample data + live demo activity</span></div></section>
 <section class="panel signal-panel"><div class="panel-heading"><div><h3>Top decision gaps</h3><p>What shoppers may be struggling with</p></div><button class="text-btn" data-action="navigate" data-target="intelligence">View all ${ic('arrow',15)}</button></div><div class="signal-list">${top.slice(0,3).map((i,index)=>`<div class="signal-item"><div class="signal-icon ${['lavender','sea','sand'][index]}">${ic(i.icon,19)}</div><div class="signal-copy"><strong>${escapeHtml(i.title)}</strong><small>${escapeHtml(i.evidenceLevel)} · ${i.count} feedback mentions</small></div><span class="signal-arrow">${ic('chevron',17)}</span></div>`).join('')}</div><div class="signal-foot">${ic('info',15)} Signals are hypotheses, not established causes.</div></section></div>
 <div class="dashboard-grid lower"><section class="panel suggestion-panel"><div class="panel-heading"><div><h3>AI-recommended next moves</h3><p>From customer evidence to real-world experiments</p></div>${badge('REVIEW REQUIRED','amber')}</div>${top.slice(0,3).map((item,i)=>`<div class="action-row"><div class="action-index">0${i+1}</div><div class="action-copy"><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.recommended)}</p></div>${badge(item.count >= 5 ? 'High signal' : 'Explore',item.count >=5?'mint':'violet')}</div>`).join('')}<button class="panel-bottom-btn" data-action="navigate" data-target="intelligence">Review evidence and recommendations ${ic('arrow',16)}</button></section>
 <section class="panel activity-panel"><div class="panel-heading"><div><h3>Agent activity</h3><p>Every action explained, never hidden</p></div><span class="activity-pulse"></span></div><div class="timeline">${d.decisions.slice(0,4).map((row,i)=>`<div class="timeline-entry"><span class="time-dot ${i===0?'latest':''}"></span><div><strong>${escapeHtml(row.title)}</strong><p>${escapeHtml(row.detail)}</p><small>${timeAgo(row.timestamp)} · ${row.seed?'Demo example':'Live demo action'}</small></div></div>`).join('')}</div><button class="panel-bottom-btn" data-action="navigate" data-target="agent">Explore your AI sales agent ${ic('arrow',16)}</button></section></div>
 <p class="demo-footnote">${ic('info',15)} All initial store metrics, feedback, and activity are synthetic demo data. Real interactions added in this workspace are also simulations.</p>`;
}
function metric(label,value,icon,detail,tone){return `<div class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon ${tone}">${ic(icon,19)}</span></div><div class="metric-number">${value}</div><div class="metric-detail"><span class="mini-pip"></span>${detail}</div></div>`;}
function intelligence(){const d=state.data,total=d.feedback.length;return `${pageHead('CUSTOMER INTELLIGENCE','See the reasons behind the numbers.','Turn voice-of-customer signals into testable business hypotheses.')}
 <div class="intelligence-intro"><span class="large-symbol">${ic('brain',34)}</span><div><h3>We look for what dashboards miss.</h3><p>Clicks tell you <em>what</em> happened. Customer evidence can suggest <em>why</em>. DecisionGap connects those signals — without pretending to read anyone's mind.</p></div><div class="evidence-count"><strong>${total}</strong><span>Feedback records</span></div></div>
 <div class="section-label-row"><h3>Prioritized decision barriers</h3><div class="evidence-notice">${ic('shield',15)} Evidence-based hypotheses</div></div>
 <div class="insight-grid">${d.insights.map((it,i)=>`<div class="insight-card"><div class="insight-top"><span class="insight-number">0${i+1} / DECISION GAP</span>${badge(it.evidenceLevel,it.count>=5?'mint':'amber')}</div><div class="insight-icon ${['lavender','sea','sand','blush','azure'][i]}">${ic(it.icon,24)}</div><h3>${escapeHtml(it.title)}</h3><p class="insight-description">${escapeHtml(it.description)}</p><div class="evidence-box"><small>VOICE OF CUSTOMER · ${it.count} MENTIONS</small><blockquote>“${escapeHtml(it.evidence[0]||'Not enough evidence yet.')}”</blockquote></div><div class="experiment-rec"><small>RECOMMENDED NEXT EXPERIMENT</small><p>${escapeHtml(it.recommended)}</p></div></div>`).join('')}</div>
 <div class="feedback-section"><div><span class="eyebrow">ADD NEW EVIDENCE</span><h2>Bring a real customer question.</h2><p>Paste anonymized feedback. The demo will classify it, update its evidence summaries, and generate revised recommendations.</p><div class="source-note">${ic('info',16)} Don't enter names, emails, payment information, or private personal details.</div></div><form id="feedback-form" class="feedback-form"><label for="feedback-input">Customer feedback</label><textarea id="feedback-input" name="feedback" minlength="12" maxlength="1000" required placeholder="Example: I wanted to order but couldn't find the full return policy until checkout..."></textarea><button type="submit" class="primary-btn">Analyze feedback ${ic('arrow',16)}</button></form></div>`;}
function agent(){const d=state.data,p=d.merchant.policy;return `${pageHead('AUTONOMOUS SALES STUDIO','A sales assistant that knows when to listen.','A transparent, guided buying experience grounded in product facts and merchant-approved rules.',`<button class="outline-btn" data-action="open-store">Talk to the live demo ${ic('arrowUp',15)}</button>`)}
 <div class="agent-main-card"><div class="agent-status-ring"><span>${ic('agent',48)}</span><i></i></div><div class="agent-card-content"><div class="agent-kicker">NOVA / SHOPPING INTELLIGENCE ASSISTANT</div><h2>Meet Nova, your AI sales teammate.</h2><p>Nova explores what customers need, explains facts clearly, recommends suitable products, prepares approved carts, and logs its decision strategies.</p><div class="agent-capabilities">${['Product discovery','Objection handling','Cart assistance','Policy guardrails'].map(t=>`<span>${ic('check',14)} ${t}</span>`).join('')}</div></div><div class="agent-availability">${badge(p.aiEnabled?'● ACTIVE':'● PAUSED',p.aiEnabled?'mint':'amber')}<small>${p.aiEnabled?(d.demo?'Available in the demo store':'Available in the connected store'):'Disabled in settings'}</small><button class="primary-btn" data-action="open-store">Open storefront ${ic('arrowUp',15)}</button></div></div>
 <div class="agents-grid"><div class="panel"><div class="panel-heading"><div><h3>How Nova makes decisions</h3><p>Decision intelligence, not blind persuasion</p></div></div><div class="process-list"><div class="process-step"><div class="process-icon">${ic('message',19)}</div><div><strong>1. Understand the customer's need</strong><p>Questions about shipping, reliability, budget or product fit become decision signals.</p></div></div><div class="process-step"><div class="process-icon">${ic('brain',19)}</div><div><strong>2. Select a permitted strategy</strong><p>Choose transparency, comparison or guidance according to the request.</p></div></div><div class="process-step"><div class="process-icon">${ic('bag',19)}</div><div><strong>3. Help the customer act</strong><p>Answer with verified facts and prepare a cart only after explicit intent.</p></div></div><div class="process-step"><div class="process-icon">${ic('chart',19)}</div><div><strong>4. Log actions and measure outcomes</strong><p>Compare test variants with real outcomes; don't infer causes from correlations.</p></div></div></div></div>
 <div class="panel rules-panel"><div class="panel-heading"><div><h3>Merchant guardrails</h3><p>You decide what the AI is allowed to do</p></div>${ic('shield',21)}</div><div class="rule-row"><span>AI selling</span>${badge(p.aiEnabled?'Enabled':'Paused',p.aiEnabled?'mint':'amber')}</div><div class="rule-row"><span>Maximum discount ceiling</span><strong>${p.maxDiscountPercent}%</strong></div><div class="rule-row"><span>Minimum margin floor</span><strong>${p.minGrossMarginPercent}%</strong></div><div class="rule-row"><span>Payment handling</span>${badge(d.demo?'Simulation only':'On Shopify checkout','neutral')}</div><div class="rule-row"><span>Policy / price changes</span>${badge('Require approval','amber')}</div><button class="panel-bottom-btn" data-action="navigate" data-target="settings">Manage guardrails ${ic('arrow',16)}</button></div></div>
 <div class="section-label-row"><h3>Recent agent decisions</h3><span class="soft-note">Showing latest 8 decisions</span></div><div class="decision-table panel"><div class="decision-table-head"><span>DECISION / ACTION</span><span>STRATEGY</span><span>RECORDED</span></div>${d.decisions.slice(0,8).map(x=>`<div class="decision-table-row"><div><strong>${escapeHtml(x.title)}</strong><small>${escapeHtml(x.detail)}</small></div><div>${badge(x.strategy||'Analysis','violet')}</div><div class="time-col">${timeAgo(x.timestamp)}${x.seed?' · sample':''}</div></div>`).join('')}</div>`;}
function experiments(){const d=state.data,variants=d.analytics.variants,max=Math.max(...variants.map(x=>x.conversion),1);return `${pageHead('EVIDENCE LAB','Test ideas. Don’t just trust them.','Compare approved sales approaches and learn from measured outcomes.')}
 <div class="experiment-banner"><div class="experiment-banner-icon">${ic('chart',30)}</div><div><span class="eyebrow">ACTIVE DEMONSTRATION</span><h2>${escapeHtml(d.experiment.name)}</h2><p>Each shopper session is consistently assigned one of two styles. ${d.demo?'Sample completed orders are synthetic and must not be presented as a real A/B lift.':'Paid orders only count after verified Shopify webhook notification.'}</p></div>${badge('● RUNNING','mint')}</div>
 <div class="variant-grid">${variants.map((v,i)=>`<div class="variant-card"><div class="variant-top"><span class="variant-letter">VARIANT ${i===0?'A':'B'}</span>${badge(i===0?'TRUST':'VALUE',i===0?'violet':'mint')}</div><h3>${escapeHtml(v.label)}</h3><p>${i===0?'Lead with verified warranties, shipping and return clarity.':'Lead with price transparency, use cases and product comparisons.'}</p><div class="variant-conversion">${v.conversion}<span>%</span><small>${d.demo?'demo conversion':'recorded conversion'}</small></div><div class="variant-bar"><i style="width:${Math.max(2,(v.conversion/max)*100)}%;background:${i===0?'#8271f5':'#43bfa9'}"></i></div><div class="variant-metrics"><div><strong>${fmt(v.visits)}</strong><span>Visitors</span></div><div><strong>${fmt(v.chats)}</strong><span>Chats opened</span></div><div><strong>${fmt(v.orders)}</strong><span>Orders</span></div></div></div>`).join('')}</div>
 <div class="experiments-grid"><section class="panel"><div class="panel-heading"><div><h3>How the experiment works</h3><p>Trustworthy experiments start with good design</p></div></div><div class="exp-rules"><div><span class="exp-number">01</span><p><strong>Consistent assignment</strong>Each visitor session is assigned to A or B deterministically.</p></div><div><span class="exp-number">02</span><p><strong>Only low-risk differences</strong>Variants change introductory wording, not prices, policies or product facts.</p></div><div><span class="exp-number">03</span><p><strong>Measure the right outcome</strong>Look at completed checkouts and business value, not chatbot messages alone.</p></div><div><span class="exp-number">04</span><p><strong>Avoid false certainty</strong>Do not declare a winning strategy without enough real randomized data.</p></div></div></section><section class="panel caveat-panel"><div class="panel-heading"><h3>Data integrity matters</h3>${ic('shield',20)}</div><div class="caveat-icon">${ic('info',27)}</div><h4>This is a demonstration, not a proven uplift.</h4><p>Initial metrics are synthetically generated. Even if one variant currently shows higher conversion, that does not establish that it is better.</p><p>For production, add power calculations, persistent visitor identity, consent, proper event attribution, and statistical analysis before making automated decisions.</p></section></div>`;}

function growth(){
 const d=state.data,plans=d.growth||[],items=d.experiments||[];
 return `${pageHead('GROWTH STUDIO','Turn customer evidence into sales experiments.','Your AI identifies candidate strategies. You approve each test before any external implementation.')}
 <div class="experiment-banner"><div class="experiment-banner-icon">${ic('brain',30)}</div><div><span class="eyebrow">AUTONOMOUS HYPOTHESIS ENGINE</span><h2>Find the next evidence-led opportunity</h2><p>These are suggested hypotheses based on recurring feedback. They are not proven reasons customers do not buy, and approval never modifies Shopify or launches advertising.</p></div>${badge('MERCHANT CONTROLLED','mint')}</div>
 <div class="insight-grid">${plans.length?plans.map(x=>`<div class="insight-card"><div class="insight-top"><span class="insight-number">${escapeHtml(x.category.toUpperCase())}</span>${badge(`${x.evidenceCount} mentions`,'mint')}</div><div class="insight-icon lavender">${ic('bolt',22)}</div><h3>${escapeHtml(x.name)}</h3><p class="insight-description">${escapeHtml(x.hypothesis)}</p><div class="evidence-box"><small>RECOMMENDED BUSINESS ACTION</small><blockquote>${escapeHtml(x.action)}</blockquote></div><div class="experiment-rec"><small>PRIMARY METRIC</small><p>${escapeHtml(x.metric)}</p></div><button class="primary-btn" data-action="make-experiment" data-plan="${x.id}">Create test draft ${ic('plus',16)}</button></div>`).join(''):`<div class="panel" style="padding:30px"><h3>No merchant feedback yet.</h3><p>Add anonymized customer feedback under Customer intelligence to generate strategy ideas.</p><button data-action="navigate" data-target="intelligence" class="primary-btn">Add evidence ${ic('arrow',17)}</button></div>`}</div>
 <div class="section-label-row"><h3>Approval & testing pipeline</h3><span class="soft-note">${items.length} total drafts and decisions</span></div>
 <div class="decision-table panel"><div class="decision-table-head"><span>PROPOSED EXPERIMENT</span><span>STATUS</span><span>MERCHANT ACTION</span></div>${items.length?items.map(x=>`<div class="decision-table-row"><div><strong>${escapeHtml(x.name)}</strong><small>${escapeHtml(x.hypothesis)} | ${escapeHtml(x.primaryMetric)}</small></div><div>${badge(x.status,x.status==='approved'?'mint':x.status==='paused'?'neutral':'amber')}</div><div>${x.status==='draft'?`<button class="outline-btn" data-action="approve-experiment" data-id="${x.id}">Approve draft</button>`:x.status==='approved'?`<button class="outline-btn" data-action="pause-experiment" data-id="${x.id}">Pause</button>`:'—'}</div></div>`).join(''):`<div style="padding:25px;color:#697086">Your proposed experiments will appear here.</div>`}</div>
 <p class="source-note" style="margin-top:20px">${ic('info',16)} Draft approval is a documented decision, not a live A/B launch. To establish causality, implement randomized treatments in your storefront and track real outcomes.</p>`;
}
function commerce(){
 const d=state.data, c=d.commerce||{};
 return `${pageHead('COMMERCE INTEGRATION','Connect your real catalog.','Use secure Shopify-hosted checkout while DecisionGap advises shoppers. Store credentials remain on your server.')}
 <div class="dashboard-grid"><section class="panel" style="padding:30px"><div class="panel-heading"><div><h3>Shopify Storefront API</h3><p>2026-07 API · credentials configured in hosting environment</p></div>${badge(c.connected?'CONFIGURED':'DEMO MODE',c.connected?'mint':'amber')}</div>
 <div class="rule-row"><span>Connection</span><strong>${c.connected?'Storefront token configured':'No credentials configured'}</strong></div>
 <div class="rule-row"><span>Store domain</span><strong>${escapeHtml(c.shopDomain||'Not configured')}</strong></div>
 <div class="rule-row"><span>Checkout</span><strong>${escapeHtml(c.checkout||'Simulation only')}</strong></div>
 <div class="rule-row"><span>Currency</span><strong>USD only in this edition</strong></div>
 <div class="rule-row"><span>Catalog</span><strong>${d.demo?'Sample products (not live)':`${d.products.length} Shopify products`}</strong></div>
 <div style="margin-top:24px"><button class="primary-btn" data-action="sync-shopify" ${c.connected?'':'disabled'}>${ic('refresh',17)} Sync live products</button> <button class="outline-btn" data-action="open-store">Visit storefront ${ic('arrowUp',16)}</button></div>
 </section><section class="panel" style="padding:30px"><h3>How to connect Shopify</h3><div class="process-list"><div class="process-step"><div class="process-icon">1</div><div><strong>Prepare Storefront API access</strong><p>Enable Storefront API permissions for viewing products and creating carts.</p></div></div><div class="process-step"><div class="process-icon">2</div><div><strong>Add secrets to your cloud host</strong><p>Set SHOPIFY_SHOP_DOMAIN and SHOPIFY_STOREFRONT_TOKEN in Render or Railway. Never put the token in the browser.</p></div></div><div class="process-step"><div class="process-icon">3</div><div><strong>Synchronize the catalog</strong><p>Press Sync live products. Existing fictional analytics are cleared the first time real products are loaded.</p></div></div><div class="process-step"><div class="process-icon">4</div><div><strong>Checkout remains on Shopify</strong><p>Customers review the cart and authorize payment on the secure Shopify checkout page.</p></div></div></div></section></div>
 <div class="feedback-section"><div><span class="eyebrow">PRODUCTION READINESS</span><h2>Never mistake a handoff for a paid sale.</h2><p>Cart creation is not payment confirmation. For paid-order reporting, configure the signed Shopify order-paid webhook and its SHOPIFY_WEBHOOK_SECRET; use a valid HTTPS callback.</p></div><div class="safe-card">${ic('shield',25)}<h3>Supported safety rules</h3><p>Server-side catalog and prices, explicit buyer checkout, verified webhook signatures, no card details in chat, merchant-controlled strategy approval.</p></div></div>`;
}
function settings(){const p=state.data.merchant.policy;return `${pageHead('MERCHANT CONTROL','You set the boundaries. AI stays inside them.','Manage what your agent can do. Agents cannot change real prices, launch campaigns, or accept payment details without explicit integrations and approval.')}
 <div class="settings-layout"><section class="panel settings-main"><div class="settings-heading"><span class="settings-icon">${ic('sliders',24)}</span><div><h3>Sales agent policies</h3><p>Changes take effect immediately in the demo storefront.</p></div></div><form id="settings-form"><div class="setting-row"><div><strong>Enable AI sales assistant</strong><p>Allow Nova to answer shoppers and help prepare their carts.</p></div><label class="switch"><input type="checkbox" name="aiEnabled" ${p.aiEnabled?'checked':''}><span class="slider"></span></label></div><div class="setting-row"><div><strong>Allow merchant-approved promotions</strong><p>Store the permitted ceiling. No promotional discount is issued automatically.</p></div><label class="switch"><input type="checkbox" name="allowDiscounts" ${p.allowDiscounts?'checked':''}><span class="slider"></span></label></div><div class="setting-row"><div><strong>Maximum discount ceiling</strong><p>A hard policy cap; not a guarantee or an active discount offer.</p></div><div class="number-input"><input type="number" name="maxDiscountPercent" min="0" max="15" value="${p.maxDiscountPercent}" required><span>%</span></div></div><div class="setting-row"><div><strong>Minimum gross margin</strong><p>Prevents future promotion tools from exceeding the merchant's chosen margin floor.</p></div><div class="number-input"><input type="number" name="minGrossMarginPercent" min="15" max="60" value="${p.minGrossMarginPercent}" required><span>%</span></div></div><div class="locked-row">${ic('lock',18)} Checkout confirmation, policy changes and real charges always require human/customer authorization in this prototype.</div><button type="submit" class="primary-btn">Save agent policies ${ic('check',17)}</button></form></section>
 <aside class="settings-side"><div class="safe-card">${ic('shield',27)}<h3>Safety by default.</h3><p>No real credit cards, automated email campaigns, uncontrolled pricing, or unverified product claims.</p><ul><li>${ic('check',16)} Merchant-defined boundaries</li><li>${ic('check',16)} Visible AI disclosure</li><li>${ic('check',16)} Explainable decisions</li><li>${ic('check',16)} Consent-led interactions</li></ul></div><div class="reset-card"><h3>Reset sample workspace</h3><p>Restore synthetic activity, feedback and settings. Removes any interactions you've generated.</p><button class="outline-btn" data-action="reset">${ic('refresh',16)} Reset demo data</button></div></aside></div>`;}
function shell(){return `<div class="dashboard-shell">${sidebar()}<div class="main-shell">${topbar()}<main class="main-content">${({overview,intelligence,agent,experiments,growth,commerce,settings})[state.page]()}</main></div></div>`;}
function storefront(){const d=state.data,products=d.products,filtered=state.filter==='All'?products:products.filter(p=>p.category===state.filter);return `<div class="shop-shell"><div class="shop-announcement">${ic('spark',15)} ${d.demo?'SAMPLE STORE — ALL PURCHASES SIMULATED':'CONNECTED SHOPIFY CATALOG — CHECKOUT ON SHOPIFY'}</div><div class="shop-nav"><div class="shop-logo"><span class="shop-star">${ic('spark',25)}</span><strong>${escapeHtml(d.storeName||'NORTHSTAR AUDIO')}</strong></div><div class="shop-navlinks"><a href="#collection" data-anchor="collection">Shop collection</a><a href="#story" data-anchor="story">Our philosophy</a><button data-action="return-dashboard">${ic('arrow',16)} DecisionGap dashboard</button></div><div class="shop-nav-actions"><span class="shop-ai-tag"><i></i> AI ASSISTED</span><button class="shop-cart-button" data-action="toggle-cart" aria-label="Open cart">${ic('bag',23)}<span>${state.cart.reduce((s,x)=>s+x.quantity,0)}</span></button></div></div>
 <section class="shop-hero"><div class="shop-hero-backdrop"><span class="shop-halo halo-one"></span><span class="shop-halo halo-two"></span></div><div class="shop-hero-copy"><span class="shop-overline">${d.demo?'HIGHER STANDARDS. BETTER SOUND.':'YOUR PRODUCTS. BETTER DECISIONS.'}</span><h1>${d.demo?'Find your<br><em>perfect frequency.</em>':'Find your<br><em>next great fit.</em>'}</h1><p>${d.demo?'Considered sound for work, travel, and everything between.':'Discover the right product for your needs, with verified details and a guided buying experience.'} Not sure where to start? Our AI shopping assistant is here to help.</p><div class="shop-hero-actions"><button class="shop-primary" data-action="browse">Shop the collection ${ic('arrow',19)}</button><button class="shop-secondary" data-action="open-chat">${ic('spark',18)} Ask Nova AI</button></div><div class="shop-points"><span>${ic('truck',17)} Shipping explained at checkout</span><span>${ic('shield',17)} ${d.demo?'30-day returns policy':'Check merchant policy terms'}</span></div></div><div class="hero-product-art"><div class="hero-product-ring ring-one"></div><div class="hero-product-ring ring-two"></div>${ic('headphones',245,'hero-headphone')}<div class="hero-product-label"><span>FEATURED PRODUCT</span><strong>${escapeHtml(products[0]?.name||'Your products')}</strong><small>From ${money(products[0]?.price||0)}</small></div></div></section>
 <section class="collection" id="collection"><div class="shop-section-head"><div><span class="shop-overline accent">THE COLLECTION</span><h2>Designed for your day.</h2><p>${d.demo?'Three distinct ways to listen. Find the one that fits you.':'Explore products from the connected Shopify catalog.'}</p></div><div class="shop-filters">${['All',...new Set(products.map(x=>x.category))].map(f=>`<button class="${state.filter===f?'active':''}" data-action="filter" data-value="${escapeHtml(f)}">${escapeHtml(f)}</button>`).join('')}</div></div><div class="products-grid">${filtered.map(p=>`<article class="product-card">${productArt(p)}<div class="product-details"><div class="product-meta">${escapeHtml(p.category)} <span class="product-stock">● IN STOCK</span></div><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.subtitle)}</p><div class="product-bottom"><div><strong>${money(p.price)}</strong><span class="struck">${money(p.compareAt)}</span></div><button data-action="select-product" data-product="${p.id}" class="round-shop-button" aria-label="Ask AI about ${escapeHtml(p.name)}">${ic('arrow',19)}</button></div></div><div class="product-quick"><button data-action="add-cart" data-product="${p.id}">${ic('plus',16)} Add to cart</button><button data-action="select-product" data-product="${p.id}">${ic('message',16)} Ask AI</button></div></article>`).join('')}</div></section>
 <section class="shop-philosophy" id="story"><div class="phil-symbol">${ic('spark',51)}</div><div><span class="shop-overline accent">AN EASIER WAY TO CHOOSE</span><h2>Less pressure.<br>More confidence.</h2><p>Great shopping isn't about being pushed to buy. It's about finding what you truly need, understanding the tradeoffs, and making a decision that feels right.</p><button data-action="open-chat">Talk to Nova AI ${ic('arrow',18)}</button></div><div class="phil-list"><div>${ic('brain',26)}<span>Guidance for your real needs</span></div><div>${ic('shield',26)}<span>Facts, policies and clarity</span></div><div>${ic('check',26)}<span>You're always in control</span></div></div></section>
 <footer class="shop-footer"><strong>${escapeHtml(d.storeName||'NORTHSTAR AUDIO')}</strong><span>${d.demo?'Fictional demo store':'Shopify-connected catalog'} · Powered by DecisionGap OS</span><button data-action="return-dashboard">Merchant dashboard ${ic('arrowUp',14)}</button></footer>
 <button class="chat-fab" data-action="open-chat"><span>${ic('spark',22)}</span><span>Ask Nova AI<small>Shopping assistant</small></span>${ic('chevron',18)}</button>${state.chatOpen?chatPanel():''}${state.cartOpen?cartPanel():''}${state.order?successModal():''}</div>`;}
function chatPanel(){const p=state.data.products.find(p=>p.id===state.selectedProduct)||state.data.products[0];return `<div class="drawer-scrim" data-action="close-chat"></div><aside class="chat-panel" role="dialog" aria-label="AI shopping assistant"><div class="chat-head"><div class="chat-agent-icon">${ic('spark',23)}</div><div><h3>Nova <span>AI</span></h3><p><i></i> Your shopping companion</p></div><button data-action="close-chat" aria-label="Close chat">${ic('close',20)}</button></div><div class="chat-notice">${ic('shield',16)} I'm an AI assistant. I use store-approved product facts, and you control checkout.</div><div class="chat-messages" id="chat-messages">${state.chatMessages.map(m=>`<div class="chat-line ${m.speaker==='buyer'?'buyer':'bot'}">${m.speaker==='agent'?`<span class="bot-badge">${ic('spark',15)}</span>`:''}<div class="chat-bubble">${escapeHtml(m.text)}</div></div>`).join('')}${state.chatLoading?`<div class="chat-line bot"><span class="bot-badge">${ic('spark',15)}</span><div class="chat-bubble typing"><i></i><i></i><i></i></div></div>`:''}</div><div class="chat-product-choice"><span>Discussing</span><select id="chat-product" aria-label="Select product">${state.data.products.map(pr=>`<option value="${pr.id}" ${pr.id===p.id?'selected':''}>${escapeHtml(pr.name)} · ${money(pr.price)}</option>`).join('')}</select></div><div class="chat-suggestions">${['Do these have a warranty?','Which product should I choose?','What about shipping?'].map(s=>`<button data-action="prompt-chat" data-value="${escapeHtml(s)}">${escapeHtml(s)}</button>`).join('')}</div><form id="chat-form" class="chat-compose"><input id="chat-input" type="text" minlength="1" maxlength="800" name="message" autocomplete="off" placeholder="Ask me anything about our products..." ${state.chatLoading?'disabled':''} required><button aria-label="Send message" type="submit" ${state.chatLoading?'disabled':''}>${ic('arrow',19)}</button></form><div class="chat-bottom-note">${ic('info',13)} Never share payment or sensitive personal details.</div></aside>`;}
function cartPanel(){const items=state.cart.map(i=>({...i,product:state.data.products.find(p=>p.id===i.productId)}));const amount=items.reduce((s,x)=>s+x.product.price*x.quantity,0);return `<div class="drawer-scrim cart-scrim" data-action="close-cart"></div><aside class="cart-panel" role="dialog" aria-label="Shopping cart"><div class="cart-head"><div><span class="shop-overline accent">YOUR BAG</span><h2>Shopping cart <span>(${items.reduce((s,x)=>s+x.quantity,0)})</span></h2></div><button data-action="close-cart" aria-label="Close cart">${ic('close',21)}</button></div><div class="cart-note">${ic('info',16)} ${state.data.demo?'Demo checkout only — no money will be collected.':'Payment is securely completed at Shopify checkout. We never collect card numbers.'}</div><div class="cart-list">${items.length?items.map(i=>`<div class="cart-item">${productArt(i.product,true)}<div><strong>${escapeHtml(i.product.name)}</strong><span>${money(i.product.price)}</span><div class="quantity-control"><button data-action="qty-minus" data-product="${i.product.id}">${ic('minus',14)}</button><em>${i.quantity}</em><button data-action="qty-plus" data-product="${i.product.id}">${ic('plus',14)}</button></div></div></div>`).join(''):`<div class="empty-cart">${ic('bag',45)}<h3>Your cart is empty</h3><p>Explore the collection or ask Nova for help finding the right product.</p><button data-action="close-cart" class="shop-primary">Keep shopping</button></div>`}</div>${items.length?`<div class="cart-summary"><div><span>Subtotal</span><strong>${money(amount)}</strong></div><small>${state.data.demo?'Shipping and any tax are not calculated or charged in this demonstration.':'Final shipping charges and applicable taxes are calculated at Shopify checkout.'}</small><button class="shop-primary full" data-action="checkout" ${state.busy?'disabled':''}>${state.busy?'Preparing checkout...':state.data.demo?'Confirm demo order':'Continue to Shopify checkout'} ${ic('arrow',18)}</button><button data-action="close-cart" class="checkout-back">Continue shopping</button></div>`:''}</aside>`;}
function successModal(){return `<div class="success-overlay"><div class="success-card"><div class="success-mark">${ic('check',35)}</div><span class="eyebrow">CHECKOUT SIMULATION COMPLETE</span><h2>Decision made.<br>Order simulated.</h2><p>This was a demonstration of AI-assisted selling. Your order was recorded in this demonstration workspace, but no payment was taken or real order submitted.</p><div class="order-details"><span>Demo order</span><strong>${escapeHtml(state.order.id)}</strong><span>Total</span><strong>${money(state.order.amount)}</strong></div><button class="primary-btn" data-action="close-success">Return to storefront ${ic('arrow',16)}</button></div></div>`;}
function loginScreen(){return `<div class="login-shell"><div class="login-card"><span class="login-icon">${ic('spark',32)}</span><p class="eyebrow">MERCHANT ACCESS</p><h1>DecisionGap <em>OS</em></h1><p>Sign in to view customer insights, simulated orders, agent decisions, and merchant settings.</p><form id="login-form" class="login-form"><label for="admin-password">Merchant password</label><input id="admin-password" name="password" type="password" autocomplete="current-password" minlength="1" maxlength="200" required placeholder="Enter your merchant password"/><button type="submit" class="primary-btn">Open dashboard ${ic('arrow',18)}</button></form>${state.loginError?`<p class="login-error">${escapeHtml(state.loginError)}</p>`:''}<div class="login-separator"></div><a href="/?view=store">Explore the public demo store ${ic('arrowUp',16)}</a><small>Private merchant data is not shared with storefront visitors.</small></div></div>`;}
function render(){if(state.loginRequired && state.view==='dashboard'){app.innerHTML=loginScreen();return;}if(!state.data){app.innerHTML='<div class="loading-screen"><span class="brand-mark">✳</span><span>Loading demo workspace...</span></div>';return;}app.innerHTML=state.view==='store'?storefront():shell();if(state.chatOpen){const feed=$('#chat-messages');if(feed)feed.scrollTop=feed.scrollHeight;}}
async function track(type,productId=''){try{await api('/api/events',{method:'POST',body:{type,sessionId,productId}})}catch(e){console.warn('Event tracking failed:',e.message);}}
function updateCart(productId,delta=1){const item=state.cart.find(x=>x.productId===productId);if(item){item.quantity=Math.max(0,Math.min(5,item.quantity+delta));if(item.quantity===0)state.cart=state.cart.filter(x=>x!==item);}else if(delta>0){state.cart.push({productId,quantity:1});track('add_to_cart',productId);}render();if(delta>0)toast(state.data.demo?'Added to your demo cart':'Added to your cart');}
async function sendChat(message){if(state.chatLoading)return;const text=message.trim();if(!text)return;state.chatMessages.push({speaker:'buyer',text});state.chatLoading=true;render();try{const response=await api('/api/chat',{method:'POST',body:{message:text,sessionId,productId:state.selectedProduct}});state.chatMessages.push({speaker:'agent',text:response.reply});if(response.action==='add_to_cart'){updateCart(response.product.id);state.cartOpen=false;state.chatOpen=true;}if(response.product?.id)state.selectedProduct=response.product.id;}catch(e){state.chatMessages.push({speaker:'agent',text:`Sorry, I couldn't respond: ${e.message}`});}finally{state.chatLoading=false;render();}}
function openChat(productId){if(productId)state.selectedProduct=productId;if(!state.chatOpen)track('chat_open',state.selectedProduct);state.chatOpen=true;state.cartOpen=false;render();}
app.addEventListener('click',async e=>{
  const actionEl=e.target.closest('[data-action]');if(!actionEl)return;
  e.preventDefault();const action=actionEl.dataset.action;const id=actionEl.dataset.product;
  if(action==='reload')location.reload();
  if(action==='logout'){
    try{await api('/api/auth/logout',{method:'POST'});}catch(e){}
    state.data=null;state.loginRequired=true;state.loginError='';render();return;
  }
  if(action==='navigate')setPage(actionEl.dataset.target);
  if(action==='download-report'){window.location.href='/api/reports/summary.csv';return;}
  if(action==='open-store')window.open('/?view=store','_blank','noopener');
  if(action==='return-dashboard')location.href='/';
  if(action==='browse')$('#collection')?.scrollIntoView({behavior:'smooth'});
  if(action==='filter'){state.filter=actionEl.dataset.value;render();}
  if(action==='open-chat')openChat();
  if(action==='select-product')openChat(id);
  if(action==='close-chat'){state.chatOpen=false;render();}
  if(action==='prompt-chat')await sendChat(actionEl.dataset.value);
  if(action==='add-cart')updateCart(id);
  if(action==='toggle-cart'){state.cartOpen=true;state.chatOpen=false;render();}
  if(action==='close-cart'){state.cartOpen=false;render();}
  if(action==='qty-plus')updateCart(id,1);
  if(action==='qty-minus')updateCart(id,-1);
  if(action==='checkout'&&!state.busy){state.busy=true;await track('checkout_start');try{const result=await api('/api/checkout',{method:'POST',body:{sessionId,items:state.cart}});if(result.checkoutUrl){window.location.assign(result.checkoutUrl);return;}state.order=result.order;state.cart=[];state.cartOpen=false;await load();toast('Demo order created. No charge was made.');}catch(err){toast(err.message,'error');}finally{state.busy=false;render();}}
  if(action==='close-success'){state.order=null;render();}
  if(action==='sync-shopify'){
    if(!confirm('Sync Shopify products? The first sync replaces fictional catalog and clears sample analytics.'))return;
    try{const result=await api('/api/commerce/sync',{method:'POST',body:{}});state.data=await api('/api/bootstrap');state.selectedProduct=state.data.products[0]?.id||'';state.cart=[];state.chatMessages=[{speaker:'agent',text:`Hi! I'm Nova, your AI shopping assistant for ${state.data.merchant.name}. How can I help you choose?`}];toast(`${result.count} Shopify products synchronized`);render();}catch(err){toast(err.message,'error');}return;
  }
  if(action==='make-experiment'){
    try{await api('/api/growth/experiments',{method:'POST',body:{playbookId:actionEl.dataset.plan}});state.data=await api('/api/bootstrap');toast('Experiment draft created');render();}catch(err){toast(err.message,'error');}return;
  }
  if(action==='approve-experiment'||action==='pause-experiment'){
    const approving=action==='approve-experiment';
    if(approving&&!confirm('Approve this proposed test? Approval does not make changes to the live storefront.'))return;
    try{await api(`/api/growth/experiments/${approving?'approve':'pause'}`,{method:'POST',body:{id:actionEl.dataset.id}});state.data=await api('/api/bootstrap');toast(approving?'Draft approved for manual implementation':'Experiment paused');render();}catch(err){toast(err.message,'error');}return;
  }
  if(action==='reset'){if(!confirm('Reset this demo workspace to the original sample data? This clears all interactions you created.'))return;try{state.data=await api('/api/reset',{method:'POST'});toast('Demo workspace reset');render();}catch(err){toast(err.message,'error');}}
});
app.addEventListener('change',e=>{if(e.target.id==='chat-product')state.selectedProduct=e.target.value;});
app.addEventListener('submit',async e=>{
  e.preventDefault();const form=e.target;
  if(form.id==='login-form'){
    const field=form.querySelector('input[name="password"]');
    try { await api('/api/auth/login',{method:'POST',body:{password:field.value}});state.loginError='';await load(); }
    catch(err){state.loginError=err.message;render();}
  }
  if(form.id==='chat-form'){const input=form.querySelector('[name="message"]');await sendChat(input.value);}
  if(form.id==='feedback-form'){
    const text=form.querySelector('textarea').value;
    try{await api('/api/feedback',{method:'POST',body:{text}});state.data=await api('/api/bootstrap');toast('Feedback analyzed. Insights updated.');render();}catch(err){toast(err.message,'error');}
  }
  if(form.id==='settings-form'){
    const field=new FormData(form);const policy={aiEnabled:field.has('aiEnabled'),allowDiscounts:field.has('allowDiscounts'),maxDiscountPercent:Number(field.get('maxDiscountPercent')),minGrossMarginPercent:Number(field.get('minGrossMarginPercent'))};
    try{await api('/api/settings',{method:'POST',body:policy});state.data=await api('/api/bootstrap');render();toast('Agent policies saved.');}catch(err){toast(err.message,'error');}
  }
});
// Every shop session counts as a visit to a sample store; dashboard inspection does not.
(async()=>{try{await load();if(state.view==='store')await track('visit');}catch(err){app.innerHTML=`<div class="loading-screen"><span class="brand-mark">!</span><h2>Couldn't start the workspace</h2><p>${escapeHtml(err.message)}</p><button data-action="reload">Try again</button></div>`;}})();
